import{_ as t,o,c as a,a2 as d}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Popover","description":"","frontmatter":{},"headers":[],"relativePath":"components/popover.md","filePath":"components/popover.md"}'),r={name:"components/popover.md"};function n(i,e,s,c,p,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="popover" tabindex="-1">Popover <a class="header-anchor" href="#popover" aria-label="Permalink to &quot;Popover&quot;">​</a></h1><p>Popover is a small surface that opens next to its trigger.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for a few settings, a small picker or an explanation that belong to one control. A list of actions is a menu (<a href="./dropdown">Dropdown</a> with <code>menu</code>); a form or a choice that stops the work is a <a href="./modal">Modal</a>; one word is a <a href="./tooltip">Tooltip</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>anchor</code></td><td>required</td><td>The trigger: a snippet of <code>(toggle, open)</code></td></tr><tr><td><code>align</code></td><td><code>start</code></td><td>The edge of the trigger it lines up with</td></tr><tr><td><code>up</code></td><td><code>false</code></td><td>Opens above the trigger, below only without room</td></tr><tr><td><code>gap</code></td><td><code>sm</code></td><td><code>0</code>, <code>sm</code>, <code>md</code> or <code>lg</code> between the children</td></tr><tr><td><code>flush</code></td><td><code>false</code></td><td>No padding and no gap: the content holds its own</td></tr><tr><td><code>openInitially</code></td><td><code>false</code></td><td>Open from the start</td></tr><tr><td><code>children</code></td><td>required</td><td>The content: a snippet of <code>(close)</code></td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The surface is a <a href="./bubble">Bubble</a>: the panel color, a strong line, the width of a popover and pad-md inside. It is placed as a <a href="./dropdown">Dropdown</a> is: in the top layer, gap-xs below the trigger (above it when there is no room below; with <code>up</code>, above it, and below only when there is no room above), gap-md inside the window at the sides, and it follows the trigger while it is open. A press outside, Escape or Tab closes it.</p><p>With <code>flush</code> the surface has no padding: the content reaches the edges and stacks with gap 0, as in a <a href="./panel">Panel</a>. Lists, trees and section headers go in directly; text and fields go in a <a href="./block">Block</a>. <code>gap</code> is not used with <code>flush</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/popover/" title="Popover" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/popover/" target="_blank" rel="noopener">Popover</a></figcaption></figure>',11)])])}const m=t(r,[["render",n]]);export{f as __pageData,m as default};
